import os
import sqlite3
import secrets
from flask import Flask, request, jsonify, g

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', secrets.token_hex(32))
DATABASE = 'db.sqlite3'


def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()


def init_db():
    with app.app_context():
        db = get_db()
        db.execute('''
            CREATE TABLE IF NOT EXISTS invitations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                invite_id TEXT UNIQUE NOT NULL,
                used INTEGER NOT NULL DEFAULT 0
            )
        ''')
        db.execute('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_name TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                email TEXT UNIQUE NOT NULL
            )
        ''')
        db.commit()


def hash_password(password):
    from passlib.hash import pbkdf2_sha256
    return pbkdf2_sha256.hash(password)


def verify_password(password, password_hash):
    from passlib.hash import pbkdf2_sha256
    try:
        return pbkdf2_sha256.verify(password, password_hash)
    except Exception:
        return False


@app.route('/invite_user', methods=['POST'])
def invite_user():
    data = request.get_json(silent=True)
    if not data or 'email' not in data:
        return jsonify({'message': 'Missing email'}), 400

    email = data['email']
    if not isinstance(email, str) or '@' not in email or len(email) < 3:
        return jsonify({'message': 'Invalid email'}), 400

    db = get_db()
    row = db.execute('SELECT invite_id FROM invitations WHERE email = ?', (email,)).fetchone()

    if row is not None:
        invite_id = row['invite_id']
    else:
        invite_id = secrets.token_urlsafe(24)
        try:
            db.execute(
                'INSERT INTO invitations (email, invite_id, used) VALUES (?, ?, 0)',
                (email, invite_id)
            )
            db.commit()
        except sqlite3.IntegrityError:
            row = db.execute('SELECT invite_id FROM invitations WHERE email = ?', (email,)).fetchone()
            if row is None:
                return jsonify({'message': 'Could not create invitation'}), 500
            invite_id = row['invite_id']

    return jsonify({
        'invite_id': invite_id,
        'message': 'Invitation id generated. Send it privately to the user email.'
    }), 200


@app.route('/create_user', methods=['POST'])
def create_user():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({'message': 'Invalid request body'}), 400

    invite_id = data.get('invite_id')
    user_name = data.get('user_name')
    password = data.get('password')

    if not invite_id or not user_name or not password:
        return jsonify({'message': 'Missing required fields'}), 400

    if not isinstance(invite_id, str) or not isinstance(user_name, str) or not isinstance(password, str):
        return jsonify({'message': 'Invalid field types'}), 400

    if len(user_name.strip()) == 0 or len(password) == 0:
        return jsonify({'message': 'Invalid user'}), 400

    db = get_db()
    invite = db.execute('SELECT * FROM invitations WHERE invite_id = ?', (invite_id,)).fetchone()
    if invite is None:
        return jsonify({'message': 'Invalid invite_id'}), 401

    if invite['used']:
        return jsonify({'message': 'Invalid invite_id'}), 401

    existing_user = db.execute('SELECT id FROM users WHERE user_name = ?', (user_name,)).fetchone()
    if existing_user is not None:
        return jsonify({'message': 'Username already exists. Try providing different username.'}), 400

    existing_email = db.execute('SELECT id FROM users WHERE email = ?', (invite['email'],)).fetchone()
    if existing_email is not None:
        return jsonify({'message': 'User already exists for this email.'}), 400

    password_hash = hash_password(password)

    try:
        db.execute(
            'INSERT INTO users (user_name, password_hash, email) VALUES (?, ?, ?)',
            (user_name, password_hash, invite['email'])
        )
        db.execute('UPDATE invitations SET used = 1 WHERE id = ?', (invite['id'],))
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        return jsonify({'message': 'Username already exists. Try providing different username.'}), 400

    return jsonify({'message': 'User created'}), 200


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
